/* tiny_cgen.c - TINY 2.1 on top of C code generated by emx-onnx-cgen.
 *
 * Nothing in here computes the network.  The network is generated/tiny2_step.c,
 * produced by the emmtrix ONNX-to-C Code Generator from training/tiny2_step.onnx:
 *
 *   void tiny2_step(tok, pos, past_k_0..3, past_v_0..3,
 *                   logits, new_k_0..3, new_v_0..3);
 *   _Bool tiny2_step_load(const char *path);     weights from tiny2_step.bin
 *
 * One call per letter, with the memory of the earlier letters handed in and
 * out as plain arrays, so this file only has to do what a host would do over
 * a serial line: feed the question letter by letter, then feed back whatever
 * letter came out until the network says the answer is over.
 *
 *   make && ./tiny_cgen
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

#ifndef TINY_NO_CLOCK
#include <time.h>
#endif

/* ---- what the generated model expects ----------------------------
 * These are the shapes in tiny2_step.onnx: 4 layers, 4 heads, 128 letters
 * of context, 24 numbers per head.  The generated function spells them out
 * in its own signature, so a model of another size needs a new generated
 * file and these four numbers changed with it. */
#define L     4
#define HEADS 4
#define CTX   128
#define HD    24
#define VOCAB 97
#define MAXQ  72

typedef float Cache[HEADS][CTX][HD];

extern _Bool tiny2_step_load(const char *path);

extern void tiny2_step(const int64_t tok[restrict 1], const int64_t pos[restrict 1],
                       const float past_k_0[restrict HEADS][CTX][HD],
                       const float past_v_0[restrict HEADS][CTX][HD],
                       const float past_k_1[restrict HEADS][CTX][HD],
                       const float past_v_1[restrict HEADS][CTX][HD],
                       const float past_k_2[restrict HEADS][CTX][HD],
                       const float past_v_2[restrict HEADS][CTX][HD],
                       const float past_k_3[restrict HEADS][CTX][HD],
                       const float past_v_3[restrict HEADS][CTX][HD],
                       float logits[restrict 1][VOCAB],
                       float new_k_0[restrict HEADS][CTX][HD],
                       float new_v_0[restrict HEADS][CTX][HD],
                       float new_k_1[restrict HEADS][CTX][HD],
                       float new_v_1[restrict HEADS][CTX][HD],
                       float new_k_2[restrict HEADS][CTX][HD],
                       float new_v_2[restrict HEADS][CTX][HD],
                       float new_k_3[restrict HEADS][CTX][HD],
                       float new_v_3[restrict HEADS][CTX][HD]);

/* The generated function may not write into the arrays it reads, so the
 * cache is kept twice and the two halves change places after every letter. */
static Cache kc[2][L], vc[2][L];
static int side;
static float logits[1][VOCAB];

static void cache_clear(void)
{
    memset(kc, 0, sizeof kc);
    memset(vc, 0, sizeof vc);
    side = 0;
}

/* feed one letter, get the scores for the next one in logits[0] */
static void step_once(int tok, int pos)
{
    const int64_t t[1] = { 0 }, p[1] = { 0 };
    int in = side, out = 1 - side;
    *(int64_t *)t = tok;
    *(int64_t *)p = pos;
    tiny2_step(t, p,
               kc[in][0], vc[in][0], kc[in][1], vc[in][1],
               kc[in][2], vc[in][2], kc[in][3], vc[in][3],
               logits,
               kc[out][0], vc[out][0], kc[out][1], vc[out][1],
               kc[out][2], vc[out][2], kc[out][3], vc[out][3]);
    side = out;
}

/* ---- choosing letters -------------------------------------------- */

static int creativity;
static unsigned long rng_state = 2463534242UL;

static unsigned long rnd(void)
{
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static int pick(void)
{
    const float *s = logits[0];
    float w[VOCAB], t, sum = 0.0f, r;
    int i, best = 0;

    for (i = 1; i < VOCAB; i++)
        if (s[i] > s[best]) best = i;
    if (creativity <= 0)
        return best;
    t = (float)creativity / 5.0f;
    for (i = 0; i < VOCAB; i++) {
        w[i] = s[i] - s[best] < -60.0f ? 0.0f : (float)exp((s[i] - s[best]) / t);
        if (w[i] < 0.15f) w[i] = 0.0f;       /* never pick unlikely letters */
        sum += w[i];
    }
    r = sum * (float)(rnd() % 10000UL) / 10000.0f;
    for (i = 0; i < VOCAB; i++) {
        r -= w[i];
        if (r < 0.0f && w[i] > 0.0f) return i;
    }
    return best;
}

/* one answer; out needs CTX + 1 bytes */
static int answer(const char *q, char *out)
{
    int pos = 0, tok, letters = 0;

    cache_clear();
    for (; q[pos]; pos++)
        step_once(q[pos] - 30, pos);
    step_once(1, pos++);                     /* end of the question         */
    for (; pos < CTX; pos++) {
        tok = pick();
        if (tok <= 1)
            break;
        out[letters++] = (char)(tok + 30);
        step_once(tok, pos);
    }
    out[letters] = '\0';
    return letters;
}

/* ---- the serial console ------------------------------------------ */

static int clean(const char *line, char *q)
{
    int i, n = 0, upper = 0, lower = 0;
    for (i = 0; line[i] && line[i] != '\n' && line[i] != '\r'; i++) {
        unsigned char c = (unsigned char)line[i];
        if (c < 32 || c > 126)
            continue;
        if (c >= 'A' && c <= 'Z') upper++;
        if (c >= 'a' && c <= 'z') lower++;
        if (c == ' ' && n == 0)
            continue;
        if (n < MAXQ)
            q[n++] = (char)c;
    }
    while (n > 0 && q[n - 1] == ' ')
        n--;
    q[n] = '\0';
    if (upper > lower)
        for (i = 0; i < n; i++)
            if (q[i] >= 'A' && q[i] <= 'Z')
                q[i] = (char)(q[i] + 32);
    return n;
}

static int same_word(const char *a, const char *b)
{
    int i;
    for (i = 0; a[i] && b[i]; i++)
        if ((a[i] | 32) != b[i]) return 0;
    return a[i] == '\0' && b[i] == '\0';
}

static int read_line(char *line, int max)
{
    int n = 0, c;
    for (;;) {
        c = getchar();
        if (c == EOF)
            return n > 0 ? (line[n] = '\0', 1) : 0;
        if (c == '\n' || c == '\r') {
            line[n] = '\0';
            return 1;
        }
        if (n < max - 1)
            line[n++] = (char)c;
    }
}

static void usage(void)
{
    printf("TINY 2.1 on C generated by emx-onnx-cgen from tiny2_step.onnx\n"
           "usage: tiny_cgen [-w FILE] [-c 0..9] [-s SEED] [-q] [-v] [-h]\n"
           "  -w FILE   generated weight file (default tiny2_step.bin)\n"
           "  -c 0..9   creativity: 0 always the surest answer, 9 the most varied\n"
           "  -s SEED   seed for the random choices (fixed by default)\n"
           "  -q        no banner, no prompt, no timing: just the answers\n"
           "  -v        what the cache costs\n"
           "Type a question and press Enter. QUIT or end of input stops.\n");
}

int main(int argc, char **argv)
{
    static char line[256], q[MAXQ + 1], out[CTX + 1];
    const char *weights = "tiny2_step.bin";
    int quiet = 0, verbose = 0, i, letters;
#ifndef TINY_NO_CLOCK
    clock_t t0;
#endif

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-w") == 0 && i + 1 < argc)
            weights = argv[++i];
        else if (strcmp(argv[i], "-c") == 0 && i + 1 < argc)
            creativity = atoi(argv[++i]);
        else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc)
            rng_state = strtoul(argv[++i], NULL, 10) | 1UL;
        else if (strcmp(argv[i], "-q") == 0)
            quiet = 1;
        else if (strcmp(argv[i], "-v") == 0)
            verbose = 1;
        else if (strcmp(argv[i], "-h") == 0) {
            usage();
            return 0;
        } else {
            printf("tiny_cgen: unknown option %s (-h for help)\n", argv[i]);
            return 2;
        }
    }
    if (creativity < 0) creativity = 0;
    if (creativity > 9) creativity = 9;

    if (!tiny2_step_load(weights)) {
        printf("tiny_cgen: cannot load %s (generated by emx-onnx-cgen)\n", weights);
        return 1;
    }
    if (verbose)
        printf("letter memory %lu bytes (%d layers x 2 x %d heads x %d x %d floats,"
               " kept twice)\n", (unsigned long)(sizeof kc + sizeof vc), L, HEADS, CTX, HD);
    if (!quiet)
        printf("TINY 2.1 ready (generated kernel). QUIT stops.\n");

    for (;;) {
        if (!quiet) {
            printf("\n> ");
            fflush(stdout);
        }
        if (!read_line(line, (int)sizeof line))
            break;
        if (clean(line, q) == 0)
            continue;
        if (same_word(q, "quit") || same_word(q, "exit"))
            break;
#ifndef TINY_NO_CLOCK
        t0 = clock();
#endif
        letters = answer(q, out);
        if (letters == 0)
            strcpy(out, ".");
        printf("%s\n", out);
#ifndef TINY_NO_CLOCK
        if (!quiet)
            printf("[%d letters, %ld ms]\n", letters,
                   (long)((double)(clock() - t0) * 1000.0 / CLOCKS_PER_SEC));
#endif
        fflush(stdout);
    }
    if (!quiet)
        printf("\nbye\n");
    return 0;
}
